"""Legacy-compatible Meridian CRM role permission check."""

_VALID_ACTIONS = frozenset({"READ", "CREATE", "UPDATE", "DELETE", "EXPORT"})


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform the action on the record."""
    if action not in _VALID_ACTIONS:
        return False

    role_id = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        # DELETE requires a record that is not already soft-deleted.
        # A blank or missing CHAR(1) boolean has legacy value 'N'.
        if action == "DELETE":
            delete_flag = record.get("DEL_FLG", "")
            if delete_flag not in ("", "N"):
                return False

        # ADMIN bypasses scope only; reaching here still required a matching row.
        if role_id == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user_team == record.get("TEAM_CD", "")
        if scope == "OWN":
            return user_id == record.get("OWNER_UID", "")
        return False

    return False
